package plates.core.values

/** The country chrome of a plate. Equal iff the codes match. Colours are ARGB. */
public class PlateCountry(
    /** ISO 3166-1 alpha-2, lower-case. */
    public val code: String,
    public val captionLines: List<String>,
    public val panelColor: Color,
    /** Null prints the wording in the theme's ink. */
    public val panelTextColor: Color?,
    public val headingLines: List<String> = emptyList(),
    public val flagAspectRatio: Double = 7.0 / 4,
    public val flag: PlateGraphic? = null,
    public val flagBorderColor: Color? = null,
) {
    override fun equals(other: Any?): Boolean = other is PlateCountry && other.code == code

    override fun hashCode(): Int = code.hashCode()
}
